'use strict';

// MODULES //

var f16 = require( '@stdlib/number/float64/base/to-float16' );
var ulpdiff = require( '@stdlib/number/float16/base/ulp-difference' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var isNegativeZero = require( '@stdlib/number/float16/base/assert/is-negative-zero' );
var isPositiveZero = require( '@stdlib/number/float16/base/assert/is-positive-zero' );


// MAIN //

/**
* Tests if two half-precision floating-point numbers are approximately the same value within a specified number of ULPs (units in the last place).
*
* ## Notes
*
* -   The function differs from the `===` operator in that the function treats `-0` and `+0` as distinct and `NaNs` as the same.
*
* @param {number} a - first input value
* @param {number} b - second input value
* @param {number} maxULP - maximum allowed ULP difference
* @returns {boolean} boolean indicating whether two half-precision floating-point numbers are approximately the same value within a specified number of ULPs
*
* @example
* var EPS = require( '@stdlib/constants/float16/eps' );
*
* var bool = isAlmostSameValue( 1.0, 1.0+EPS, 1 );
* // returns true
*
* bool = isAlmostSameValue( 1.0+EPS, 1.0, 1 );
* // returns true
*
* bool = isAlmostSameValue( 1.0, 1.0+EPS+EPS, 1 );
* // returns false
*
* bool = isAlmostSameValue( 1.0, 1.0+EPS, 0 );
* // returns false
*
* bool = isAlmostSameValue( 0.0, -0.0, 0 );
* // returns false
*
* bool = isAlmostSameValue( 1.0, NaN, 1 );
* // returns false
*
* bool = isAlmostSameValue( NaN, NaN, 1 );
* // returns true
*/
function isAlmostSameValue( a, b, maxULP ) {
	var af;
	var bf;

	af = f16( a );
	bf = f16( b );

	// Handle NaN values (NaN === NaN in SameValue):
	if ( isnan( af ) && isnan( bf ) ) {
		return true;
	}
	// Handle signed zeros (-0 !== +0 in SameValue):
	if ( isPositiveZero( af ) && isNegativeZero( bf ) ) {
		return false;
	}
	if ( isNegativeZero( af ) && isPositiveZero( bf ) ) {
		return false;
	}
	// Check if exactly the same:
	if ( af === bf ) {
		return true;
	}
	// Check ULP difference:
	return ulpdiff( af, bf ) <= maxULP;
}


// EXPORTS //

module.exports = isAlmostSameValue;
